    'local_currency_step_6' => 'Se mostrará el método de depósito disponible y deberás seleccionar tu método de pago preferido e ingresar el monto del depósito.',
    'local_currency_step_7' => 'Inicia sesión en tu banco o proporciona los detalles de tu pago.',
    'local_currency_step_8' => 'Revisa los detalles y acepta la transacción.',
